import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Apply scene placement
  group.position.set(...(config.scenePosition || [0, 3, 0]));
  if (config.sceneRotation) {
    group.rotation.set(...config.sceneRotation);
  }
  if (config.sceneScale) {
    group.scale.set(...config.sceneScale);
  }

  const resourcesToDispose = [];
  const timelinesToKill = [];

  // Load image texture
  const imageTexture = ctx.textureLoader.load(config.assets.imageUrl);
  resourcesToDispose.push(imageTexture);

  // Create plane geometry (512:320 aspect ratio ≈ 1.6:1)
  const planeGeometry = new THREE.PlaneGeometry(2.4, 1.5);
  resourcesToDispose.push(planeGeometry);

  // Create material with image texture
  const planeMaterial = new MeshBasicNodeMaterial({
    map: imageTexture
  });
  resourcesToDispose.push(planeMaterial);

  // Create and add plane mesh
  const planeMesh = new THREE.Mesh(planeGeometry, planeMaterial);
  group.add(planeMesh);

  // Render text content if available
  if (config.textContent && ctx.fontAtlas) {
    try {
      const textGeometry = ctx.fontAtlas.createGeometry(
        config.textContent,
        {
          font: 'JetBrains Mono',
          size: 0.031,
          weight: 400,
          color: 0x16161d,
          align: 'left',
          width: 2.2
        }
      );

      if (textGeometry) {
        textGeometry.position.set(0, -0.9, 0.01);
        group.add(textGeometry);
        resourcesToDispose.push(textGeometry);
      }
    } catch (error) {
      // fontAtlas unavailable; continue without text
    }
  }

  // Define cleanup function
  group.userData.cleanup = () => {
    resourcesToDispose.forEach(resource => {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    });

    timelinesToKill.forEach(timeline => {
      if (timeline && typeof timeline.kill === 'function') {
        timeline.kill();
      }
    });
  };

  return group;
}
